import { readCapabilities, revokeOnAdminFailure } from './AdminAccess';
import { adminWorkspace } from './adminWorkspace';
import type { AdminGuard } from './adminTransport';

const maximumBytes = 10 * 1024 * 1024;
const artworkPath = /^\/api\/admin\/v1\/catalog\/(?:album|artist|audioTrack)\/[a-f0-9]{24}\/artwork$/;
let active = 0;
const waiting: Array<() => void> = [];

/** Keeps legacy fetches below their two-worker budget and leaves media admission for playback. */
async function withArtworkSlot<T>(signal: AbortSignal, work: () => Promise<T>): Promise<T> {
  signal.throwIfAborted();
  await new Promise<void>((resolve, reject) => {
    const cancel = () => {
      const index = waiting.indexOf(start);
      if (index >= 0) waiting.splice(index, 1);
      reject(signal.reason);
    };
    const start = () => {
      signal.removeEventListener('abort', cancel);
      active++;
      resolve();
    };
    if (active < 2) start();
    else if (waiting.length < 64) {
      waiting.push(start);
      signal.addEventListener('abort', cancel, { once: true });
    } else reject(new Error('Catalog artwork queue is full.'));
  });
  try { signal.throwIfAborted(); return await work(); }
  finally { active--; waiting.shift()?.(); }
}

/** Retry-After is a minimum wait; a longer server cooldown ends this bounded attempt. */
function retryDelay(value: string | null, attempt: number) {
  const seconds = value?.trim() && /^\d+(?:\.\d+)?$/.test(value.trim()) ? Number(value) * 1000 : NaN;
  const parsed = Number.isFinite(seconds) ? seconds : value ? Date.parse(value) - Date.now() : NaN;
  const delay = Number.isFinite(parsed) ? Math.max(250, parsed) : 2000 * (attempt + 1);
  return delay <= 30_000 ? delay : null;
}

/** A view transition cancels cooldowns before any queued retry can send another private read. */
async function waitForRetry(delay: number, signal: AbortSignal) {
  signal.throwIfAborted();
  await new Promise<void>((resolve, reject) => {
    const cancel = () => { clearTimeout(timer); reject(signal.reason); };
    const timer = setTimeout(() => { signal.removeEventListener('abort', cancel); resolve(); }, delay);
    signal.addEventListener('abort', cancel, { once: true });
  });
}

/** Fully reads only allowlisted, size-bounded raster bytes before creating a private object URL. */
async function readArtwork(response: Response, signal: AbortSignal) {
  const type = response.headers.get('Content-Type')?.split(';')[0].trim().toLowerCase();
  const length = response.headers.get('Content-Length');
  if (!type || !['image/jpeg', 'image/png', 'image/webp', 'image/gif'].includes(type)
    || length !== null && (!/^\d+$/.test(length) || Number(length) > maximumBytes) || !response.body) {
    await response.body?.cancel();
    throw new Error('Invalid catalog artwork response.');
  }
  const reader = response.body.getReader();
  const chunks: Uint8Array<ArrayBuffer>[] = [];
  let size = 0;
  try {
    while (true) {
      signal.throwIfAborted();
      const { done, value } = await reader.read();
      signal.throwIfAborted();
      if (done) break;
      size += value.byteLength;
      if (size > maximumBytes) throw new Error('Catalog artwork is too large.');
      chunks.push(new Uint8Array(value));
    }
    if (!size || length !== null && size !== Number(length)) throw new Error('Incomplete catalog artwork.');
    return new Blob(chunks, { type });
  } catch (error) { await reader.cancel().catch(() => {}); throw error; }
  finally { reader.releaseLock(); }
}

/** Private cover reads never outlive their captured account, view generation or authority. */
export async function loadCatalogArtwork(path: string, guard: AdminGuard, signal: AbortSignal): Promise<Blob> {
  if (!artworkPath.test(path)) throw new Error('Invalid catalog artwork path.');
  const current = () => {
    signal.throwIfAborted();
    if (!adminWorkspace.current(guard)) throw new DOMException('Admin view changed', 'AbortError');
  };
  let refreshed = false;
  for (let attempt = 0; ; attempt++) {
    current();
    const result = await withArtworkSlot<{ blob: Blob } | { status: number; delay: number | null }>(signal, async () => {
      current();
      // Fetch abort covers headers and body; queued work does not consume this network deadline.
      const deadline = new AbortController();
      const timer = setTimeout(() => deadline.abort(new DOMException('Artwork read timed out', 'TimeoutError')), 15_000);
      const requestSignal = AbortSignal.any([signal, deadline.signal]);
      try {
        const response = await fetch(`${path}?viewer=${encodeURIComponent(guard.viewerId)}`, {
          credentials: 'same-origin', cache: 'no-store', redirect: 'error', signal: requestSignal,
          headers: { Accept: 'image/*', 'X-Finitude-Account-Viewer': guard.viewerId }
        });
        try { current(); }
        catch (error) { await response.body?.cancel(); throw error; }
        if (!response.ok) {
          const delay = retryDelay(response.headers.get('Retry-After'), attempt);
          await response.body?.cancel();
          return { status: response.status, delay };
        }
        if (response.headers.get('X-Finitude-Account-Viewer') !== guard.viewerId) {
          await response.body?.cancel();
          throw new Error('Catalog artwork viewer changed.');
        }
        const blob = await readArtwork(response, requestSignal);
        current();
        return { blob };
      } finally { clearTimeout(timer); }
    });
    current();
    if ('blob' in result) return result.blob;
    if (result.status === 401 && !refreshed) {
      refreshed = true;
      // A bound admin read uses the shared, coalesced cookie rotation without adopting a new account epoch.
      try { await readCapabilities(guard.viewerId, signal); }
      catch (error) {
        if (adminWorkspace.current(guard, false)) revokeOnAdminFailure(error);
        throw error;
      }
      current();
      continue;
    }
    if ([401, 403].includes(result.status)) adminWorkspace.reset();
    if (attempt >= 2 || ![429, 502, 503, 504].includes(result.status) || result.delay === null) {
      throw new Error('Catalog artwork is unavailable.');
    }
    await waitForRetry(result.delay, signal);
  }
}
